      "rubric_stage3": "I understand that students have varying traumatic experiences and I am aware of how students’ trauma may influence their behaviors. In the moment, I make efforts to prevent situations that might cause harm or trigger students. I am consistently effective in my use of de-escalation strategies when students are triggered.",
      "rubric_stage4": "I understand that students have varying traumatic experiences and I am aware of how students’ trauma may influence their behaviors. I proactively make efforts to prevent situations that might cause harm or trigger students. I am consistently effective in my use of de-escalation strategies when students are triggered.",
      "rubric_stage1_vi": "Tôi chưa nhận thức đầy đủ về tác động của chấn thương tâm lý lên hành vi của học sinh và đôi khi vô tình kích động học sinh khiến hành vi leo thang.",
      "rubric_stage2_vi": "Tôi nhận thức được chấn thương tâm lý có thể ảnh hưởng đến học sinh và cố gắng không kích động hành vi tiêu cực. Đôi khi tôi cần các chiến lược hỗ trợ khi học sinh bị kích động.",
      "rubric_stage3_vi": "Tôi hiểu học sinh có trải nghiệm chấn thương tâm lý khác nhau và nhận thức được điều này ảnh hưởng ra sao đến hành vi. Tại thời điểm đó, tôi nỗ lực ngăn ngừa các tình huống gây tổn thương hoặc kích động học sinh. Tôi áp dụng hiệu quả và nhất quán các chiến lược hạ nhiệt tâm lý khi học sinh bị kích động.",
      "rubric_stage4_vi": "Tôi hiểu học sinh có các trải nghiệm chấn thương khác nhau và nhận thức sâu sắc ảnh hưởng của nó đến hành vi. Tôi chủ động ngăn ngừa từ sớm mọi tình huống có thể gây tổn thương hoặc kích động học sinh. Tôi luôn áp dụng hiệu quả và nhất quán các chiến lược hạ nhiệt tâm lý khi học sinh bị kích động.",
      "example_stage1_vi": "Khi học sinh đập bàn phản kháng, giáo viên phạt đứng hoặc ghi sổ.",
