      "example_stage4_vi": "Giáo viên thiết kế sẵn quy trình hạ nhiệt, học sinh tự biết chọn chiến lược điều hòa cảm xúc.",
      "example_stage1": "When a student acts out, teacher reacts with immediate disciplinary write-ups.",
