      "rubric_stage1": "I sometimes use formative assessments (e.g. self-assessment, exit tickets, student surveys) to ensure students have gained the necessary skills and knowledge.",
      "rubric_stage2": "I sometimes use formative assessments (e.g. self-assessment, exit tickets, student surveys) in a timely manner to monitor learner progress, guide my decision making and instructional practice, and ensure students have gained the necessary skills and knowledge to complete the performance-based assessments.",
      "rubric_stage3": "I use frequent formative assessments (e.g. self-assessment, exit tickets, student surveys) in a timely manner to monitor learner progress, guide my decision making and instructional practice, and ensure students have gained the necessary skills and knowledge to complete the performance-based assessments at the desired level on the continua.",
